const info=async pid=>{assert(Number.isInteger(pid)&&pid>0);const helper=path.join(receipt.packageRoot,'runtime/freemix-process-info.exe'),p=JSON.parse((await run(helper,[String(pid)],{windowsHide:true,timeout:5000})).stdout)[0];assert.equal(p.pid,pid);if(!p.path&&!p.exited){const ps="@(Get-CimInstance Win32_Process -Filter 'ProcessId = "+pid+"') | Select-Object ProcessId,ExecutablePath,CreationDate | ConvertTo-Json -Compress",result=await run('powershell.exe',['-NoProfile','-NonInteractive','-Command',ps],{windowsHide:true,timeout:5000}),raw=result.stdout.trim(),rows=raw?JSON.parse(raw):[],array=Array.isArray(rows)?rows:[rows];assert(array.length<=1);if(!array.length){receipt.processObservations.push({pid,helperUnknown:true,cimQuerySucceeded:true,cimAbsent:true});return {...p,exited:true,confirmedBy:'Successful read-only CIM absent query'};}assert.equal(array[0].ProcessId,pid);receipt.processObservations.push({pid,helperUnknown:true,cimQuerySucceeded:true,cimPresent:true,executablePathAvailable:!!array[0].ExecutablePath,creationDate:array[0].CreationDate});return {...p,path:array[0].ExecutablePath||null,creationDate:array[0].CreationDate,confirmedBy:'Read-only CIM fallback'};}return p;};
